package test

import (
	"fmt"
	"testing"
	"time"
)

// TestProtocols drives real traffic through every supported inbound type using the
// client outbound generated by the user's own sing-box subscription, and checks
// per-inbound accounting.
func TestProtocols(t *testing.T) {
	e := newEnv(t)
	uid := e.createUser(map[string]any{"username": "multi"})
	insecure := map[string]any{"insecure": true}
	tls := e.tlsFiles()
	quic := func() map[string]any { m := e.tlsFiles(); m["alpn"] = []string{"h3"}; return m }
	cases := []struct {
		tag, typ string
		opts     map[string]any
		client   map[string]any
	}{
		{"vless-reality", "vless", e.realityOpts(freePort(t)), nil},
		{"vless-ws", "vless", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t), "transport": map[string]any{"type": "ws", "path": "/w"}}, nil},
		{"vless-grpc-tls", "vless", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t), "tls": tls, "transport": map[string]any{"type": "grpc", "service_name": "g"}}, insecure},
		{"vmess-ws-tls", "vmess", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t), "tls": tls, "transport": map[string]any{"type": "ws", "path": "/v"}}, insecure},
		{"vmess-tcp", "vmess", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t)}, nil},
		{"trojan-tls", "trojan", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t), "tls": tls}, insecure},
		{"trojan-httpupgrade", "trojan", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t), "tls": tls, "transport": map[string]any{"type": "httpupgrade", "path": "/u"}}, insecure},
		{"ss2022", "shadowsocks", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t), "method": "2022-blake3-aes-128-gcm", "password": "dGVzdHRlc3R0ZXN0dGVzdA=="}, nil},
		{"hysteria2", "hysteria2", map[string]any{"listen": "127.0.0.1", "listen_port": freeUDPPort(t), "tls": quic()}, insecure},
		{"tuic", "tuic", map[string]any{"listen": "127.0.0.1", "listen_port": freeUDPPort(t), "congestion_control": "bbr", "tls": quic()}, insecure},
		{"anytls", "anytls", map[string]any{"listen": "127.0.0.1", "listen_port": freePort(t), "tls": tls}, insecure},
	}
	for _, c := range cases {
		e.createInbound(c.tag, c.typ, c.opts, c.client)
	}
	e.waitApplied()
	outs := e.subOutbounds(uid)
	target := blob(t)
	const size = 4 << 20
	for _, c := range cases {
		t.Run(c.tag, func(t *testing.T) {
			ob, ok := outs["local · "+c.tag]
			if !ok {
				t.Fatalf("no outbound in subscription (have %v)", keys(outs))
			}
			proxy := client(t, ob)
			var err error
			for attempt := 0; attempt < 3; attempt++ { // QUIC handshakes can race the first request
				if _, err = fetch(proxy, target, size, "", 60*time.Second); err == nil {
					break
				}
				time.Sleep(500 * time.Millisecond)
			}
			if err != nil {
				t.Fatalf("download through %s: %v", c.tag, err)
			}
		})
	}
	e.settle(uid)
	var rows []struct {
		Key  string `json:"key"`
		Down int64  `json:"down"`
	}
	e.api.do("GET", "/api/traffic/top?dim=inbound&limit=100", nil, &rows)
	got := map[string]int64{}
	for _, r := range rows {
		got[r.Key] = r.Down
	}
	for _, c := range cases {
		k := fmt.Sprintf("%s/%s", e.nodeID, c.tag)
		if got[k] < size {
			t.Errorf("%s accounted %d bytes, want >= %d", c.tag, got[k], size)
		} else {
			t.Logf("%-20s %d bytes (+%d overhead)", c.tag, got[k], got[k]-size)
		}
	}
}
